from collections import Counter


def transform(grid):
    """Slide the non-divider motif toward a full line and mark its far edge."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            lines.append(("row", r, row[0]))
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and next(iter(vals)) != bg:
            lines.append(("col", c, next(iter(vals))))
    if not lines:
        raise ValueError("no full-length divider")
    orient, divider, divider_color = lines[0]
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, divider_color)]
    if not cells:
        raise ValueError("no motif")
    axis_vals = [r if orient == "row" else c for r, c, _ in cells]
    lo, hi = min(axis_vals), max(axis_vals)
    side = 1 if lo > divider else -1
    shift = (divider + 1 - lo) if side == 1 else (divider - 1 - hi)
    out = [row[:] for row in grid]
    for r, c, _ in cells:
        out[r][c] = bg
    for r, c, color in cells:
        nr, nc = (r + shift, c) if orient == "row" else (r, c + shift)
        if not (0 <= nr < h and 0 <= nc < w):
            raise ValueError("translated motif out of bounds")
        out[nr][nc] = color
    far_edge = (hi + shift) if side == 1 else (lo + shift)
    stripe = far_edge + side
    if orient == "row":
        if not 0 <= stripe < h:
            raise ValueError("marker line out of bounds")
        out[stripe] = [8] * w
    else:
        if not 0 <= stripe < w:
            raise ValueError("marker line out of bounds")
        for r in range(h):
            out[r][stripe] = 8
    return out


